  V=np.array([lam**j for j in range(s)]).T;cs=np.linalg.solve(V.T@(w[:,None]*V),V.T@(w*lam**s));vals=lam**s-V@cs
  z=w*vals**2;return z/z.sum()
 def F(w):return T(T(w))
 def H(w):return np.sum(nu*np.log(w))
 pos=0;mi=0;ma=-1
 for rep in range(5000):
